#!/usr/bin/env bun
/**
 * Generates per-framework SSR HTML fixtures for the hydration bench.
 *
 * Runs in bun (workspace `bun` condition → Pyreon src). Each framework's HTML
 * comes from its OWN server renderer over the SAME shared component module the
 * browser hydrates — the only sound setup: React/Vue/Preact hydration ADOPTS
 * nodes only when the markup matches what their renderer would emit, and
 * Pyreon's SSR emits the For key markers hydrateRoot consumes.
 *
 * Output: public/hydration-fixtures.json (NOT committed — generated by the
 * driver before `vite build`; vite serves/copies public/ verbatim, and the
 * page fetches it at runtime, so neither typecheck nor the build depend on
 * the generated file existing).
 */
import { mkdirSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

process.env.NODE_ENV = 'production'

const { renderToString: pyreonRender } = await import('@pyreon/runtime-server')
const { renderToString: reactRender } = await import('react-dom/server')
const { renderToString: preactRender } = await import('preact-render-to-string')
const { renderToString: vueRender } = await import('@vue/server-renderer')
const { createSSRApp } = await import('vue')
const { signal } = await import('@pyreon/reactivity')

const { buildFixtureRows, HYDRATION_ROW_COUNT, pyreonApp, reactApp, preactApp, vueApp } =
  await import('../src/impl/hydration-shared')

const rows = buildFixtureRows(HYDRATION_ROW_COUNT)

// Pyreon — the client hydrates with per-row signals; the fixture renders the
// SAME component shape with signals seeded from the fixture data.
const pyreonRows = rows.map((r) => ({ id: r.id, label: signal(r.label) }))
const pyreonHtml = await pyreonRender(
  pyreonApp(
    () => pyreonRows,
    () => false,
    () => {},
  ),
)

const reactHtml = reactRender(reactApp(rows, null, () => {}))
const preactHtml = preactRender(preactApp(rows, null, () => {}))
const vueHtml = await vueRender(createSSRApp(vueApp(rows).component))

// Sanity: every fixture must contain all 1000 rows.
for (const [name, html] of Object.entries({
  pyreon: pyreonHtml,
  react: reactHtml,
  preact: preactHtml,
  vue: vueHtml,
})) {
  const count = (html.match(/<tr/g) ?? []).length
  if (count !== HYDRATION_ROW_COUNT) {
    throw new Error(`[gen-hydration-fixtures] ${name}: expected ${HYDRATION_ROW_COUNT} <tr>, got ${count}`)
  }
}

const out = {
  rows,
  html: { pyreon: pyreonHtml, react: reactHtml, preact: preactHtml, vue: vueHtml },
}
const dir = join(import.meta.dirname, '../public')
mkdirSync(dir, { recursive: true })
writeFileSync(join(dir, 'hydration-fixtures.json'), JSON.stringify(out))
console.log(
  `[gen-hydration-fixtures] wrote ${Object.keys(out.html).length} fixtures (${HYDRATION_ROW_COUNT} rows; pyreon=${(pyreonHtml.length / 1024).toFixed(1)}KB react=${(reactHtml.length / 1024).toFixed(1)}KB preact=${(preactHtml.length / 1024).toFixed(1)}KB vue=${(vueHtml.length / 1024).toFixed(1)}KB)`,
)
